Fix $x\in V(G)$ and suppose $\{X_n^x\}_{n\geq0}$ is a simple random walk on $G$ starting at $x$. Let $n\vee 1=\max\{ 1,n\}$ denote the maximum of $n$ and $1$.
  	Then 
 	\begin{equation}
 	\mathbb{E}\left[\sum_{k=0}^{\infty}\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\right]\asymp 1
 	\ \textnormal{ and }\ 
 	\mathbb{E}\left[\sum_{k=0}^{\infty}k\cdot\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\right]\asymp n\vee 1.
 	\end{equation}



 	For an integer $n\geq0$, let $\tau_{-n}^x:=\sup\{k:X_k\in L_{-n}(x)\}$ be the last visit time of the slab $L_{-n}(x)$. Then there exist constants $c_1,c_2,c_3>0$ such that 
 	\begin{equation} 
 	\mathbb{P}[\tau_{-n}^x\geq R]\leq c_1\exp(-c_2R),\ \ \forall \ R\geq c_3(n\vee 1).
 	\end{equation}

There exists positive constants $c_{1},c_{2}$ such that for all $n\geq0$,
 	\begin{equation}
 	c_{1}\leq \mathbb{E}[|\mathfrak{T}_x\cap L_{-n}(x)|]\leq c_{2}
 	\end{equation}
 	and 
 	\begin{equation}
 		c_{1}\exp(-t_0(n+1))\leq \mathbb{E}[|\mathfrak{T}_x\cap L_{n}(x)|]\leq c_{2}\exp(-t_0(n-1)).
 	\end{equation}

There exist  constants $c_1>0,c_{2}>1$ such that for every $n\geq1$
 		\begin{equation}
 		1\leq \mathbb{E}[|T_x\cap L_{0}(x)|]\leq c_{2}\textnormal{ and }
 		c_1n\leq \mathbb{E}[|T_x\cap L_{-n}(x)|]\leq c_{2}n
 		\end{equation}
 and
 	\begin{equation}
 	c_1n\exp(-t_0(n+1))\leq \mathbb{E}[|T_x\cap L_{n}(x)|]\leq c_{2}n\exp(-t_0(n-1)), \ \forall n\geq1
 	\end{equation}

There exists a constant $c_{1}>0$ such that for every $n\geq0$,
 	\begin{equation}
 	1\leq \mathbb{E}[|\mathfrak{F}(x,\infty)\cap L_{-n}(x)|]\leq c_{1}.
 	\end{equation}
 	There exists  constants $c_{2},c_{3}>0$ such that for every $n\geq1$,
 	\begin{equation}
 	c_{2}\leq\mathbb{E}[|\mathfrak{P}(x)\cap L_{-n}(x)|]\leq c_{3}e^{t_0}.
 	\end{equation}
 	Moreover one also has that
 	\begin{equation}
 	c_{2}\exp(-t_0(n+1))\leq \mathbb{E}[|\mathfrak{F}(x,\infty)\cap L_{n}(x)|]\leq c_{3}\exp(-t_0n)
 	\end{equation}
 	and
 	\begin{equation}
 		\exp(-t_0(n+1))\leq \mathbb{E}[|\mathfrak{P}(x)\cap L_{n}(x)|]\leq c_{1}\exp(-t_0(n-1)).
    \end{equation}

Let $\{T_x\cap L_n(x)\neq \emptyset\}$ denote the event that $T_x$ has a nonempty intersection with the slab $L_n(x)$. Then for $n\geq1$
 	\begin{equation}
  \mathbb{P}[T_x\cap L_n(x)\neq \emptyset]\asymp n\exp(-t_0n).
 	\end{equation}
 	In particular
 	\begin{equation}
 	\lim_{n\rightarrow\infty}-\frac{1}{t_0n}\log\mathbb{P}[T_x\cap L_n(x)\neq \emptyset]=1.
 	\end{equation}

For the tree $\mathfrak{T}_x$ in the $x$-WUSF and $n\geq 0$, one  has
	\begin{equation}
	\mathbb{P}[\mathfrak{T}_x\cap L_{n}(x)\neq \emptyset]\asymp \exp(-t_0n)
	\end{equation}

	In particular,  
	\begin{equation}
	\lim_{n\rightarrow\infty}-\frac{1}{t_0n}\log\mathbb{P}[\mathfrak{T}_x\cap L_{n}(x)\neq \emptyset]=1.
	\end{equation}
	Moreover for $n\geq 1$, the decay of $\mathbb{P}[\mathfrak{T}_x\cap L_{-n}(x)\neq \emptyset]$ is much slower.
	\begin{equation}
	\mathbb{P}[\mathfrak{T}_x\cap L_{-n}(x)\neq \emptyset]\asymp\frac{1}{n}.
	\end{equation}

Suppose $n\geq0$. For the future one has the following asymptotic behavior:
	\begin{equation}
	\mathbb{P}[\mathfrak{F}(x,\infty)\cap  L_n(x)\neq\emptyset]\asymp \exp(-t_0n)
	\end{equation}
	For the past one has 
	\begin{equation}
	   \mathbb{P}[\mathfrak{P}(x)\cap  L_n(x)\neq\emptyset]\asymp \exp(-t_0n)
	\end{equation}
	and
	\begin{equation}
	\mathbb{P}[\mathfrak{P}(x)\cap  L_{-n}(x)\neq\emptyset]\asymp\frac{1}{n\vee 1}.
	\end{equation}

There exists $c_{1}>0$ such that for all $n\geq0,k\geq 2$, one has 
 	\begin{equation}
 	\mathbb{E}[|\mathfrak{T}_x\cap L_n(x)|^k]\leq c_{1}^k(k!)^{2}\exp(-t_0n)
 	\end{equation}
 	and 
 	\begin{equation}
 		\mathbb{E}[|\mathfrak{T}_x\cap L_{-n}(x)|^k]\leq c_{1}^k(k!)^{2} (n\vee 1)^{k-1}.
 	\end{equation}

For the future $\mathfrak{F}(x,\infty)$, there exists a constant $c>0$ such that 
  	\[
  	\mathbb{E}[|\mathfrak{F}(x,\infty)\cap L_{n}(x)|^k]\leq 
  	\left\{
  	\begin{array}{cc}
  	c^kk!e^{-t_0n} & \textnormal{ if }n\geq0\\
  	c^kk!& \textnormal{ if }n<0
  	\end{array}
  	\right.
  	\]
  }

For all $n\geq0,k\geq2$ there exists a constant $c_{1}>0$ such that 
 	\begin{equation}
 	\mathbb{E}[|T_x\cap L_n(x)|^k]\leq  c_{1}^k(k!)^5(n\vee 1)e^{-t_0n}
 	\end{equation}
 	and
 	\begin{equation}
 	\mathbb{E}[|T_x\cap L_{-n}(x)|^k]\leq c_{1}^k(k!)^5(n\vee 1)^{2k}.
 	\end{equation}

Suppose $\mathfrak{F}(x,\infty)=(x_0,x_1,x_2,\ldots)$ is the future of $x$ in the WUSF sample $\mathfrak{F}$. Let $\mathfrak{T}_{x_i}$ be the tree of $x_i$ in  $x_i$-WUSF, sampled independently of  $\mathfrak{F}$, $U$ and each other. Then for every $n\in\mathbb{Z},k\geq 2$, one has
 	\begin{equation}
 	\mathbb{E}\big[|T_x\cap L_n(x)|^k\bigm|\mathfrak{F}(x,\infty),U\big]
 	\leq k! \sum_{\substack{k_0,k_1,\ldots \geq 0:\\ k_0+ k_1+\cdots  =k}} \, \prod_{i:k_i\neq 0} \frac{1}{k_i!}\mathbb{E}\big[|\mathfrak{T}_{x_i}\cap L_n(x)|^{k_i}\bigm|U\big]. 
 	\end{equation}

There exists a constant $c>0$ such that for all $n\geq0,k\geq2$, 
 	\[
 	\mathbb{E}[|\mathfrak{P}(x)\cap L_n(x)|^k]\leq \left\{
 	\begin{array}{cc}
 	c^k(k!)^2e^{-t_0n} &\textnormal{ if }n\geq0\\
 		c^k(k!)^2|n|^{k-1} & \textnormal{ if }n<0
 	\end{array}
 	\right..
 	\]
 }

Let $G$ be an infinite network and $\mathfrak{F}$ be a sample of OWUSF on $G$. For each $v\in V(G)$, let $\mathfrak{F}_v$ be an oriented $v$-WUSF of $G$. Suppose $K$ is a finite set of vertices of $G$ and define $F(K):=\bigcup_{u\in K}\mathfrak{F}(u,\infty)$ and $F_v(K):=\bigcup_{u\in K}\mathfrak{F}_v(u,\infty)$. Then for every $u\in K$ and every increasing event $\mathscr{A}\subset \{0,1\}^E$ we have 
 	\begin{equation}
 	\mathbb{P}\left( \textnormal{past}_{\mathfrak{F}\backslash F(K)}(u)\in\mathscr{A}\mid F(K)\right)
 	\leq \mathbb{P}(\mathfrak{T}_u\in\mathscr{A})
 	\end{equation}
 	and similarly
 	\begin{equation}
 	\mathbb{P}\left( \textnormal{past}_{\mathfrak{F}_v\backslash F_v(K)}(u)\in\mathscr{A}\mid F(K)\right)
 	\leq \mathbb{P}(\mathfrak{T}_u\in\mathscr{A}).
 	\end{equation}

For $\lambda>0$, the tilted volume $|T_x|_{x,\lambda}$ has the following property.
	\begin{equation}
		 \mathbb{P}[|T_x|_{x,\lambda}\geq R]\asymp_{\lambda} R^{-\frac{1}{\lambda}}\log R , \ \forall\  R\geq 2.
		\end{equation}

The tail probability  $\mathbb{P}[|\mathfrak{T}_x|_{x,\lambda}\geq R]$ satisfies the following inequalities. 
	\begin{itemize}
		\item If $\lambda<0$, then 
		\begin{equation}
		\mathbb{P}[|\mathfrak{T}_x|_{x,\lambda}\geq R]\asymp_{\lambda} \frac{1}{\log R},\, R\geq 2.
		\end{equation}

		\item  If $\lambda=0$, then $|\mathfrak{T}_x|_{x,\lambda}=|\mathfrak{T}_x|$ is the size of the tree $\mathfrak{T}_x$ and 
		\begin{equation}
			\mathbb{P}[|\mathfrak{T}_x|\geq R]\asymp \frac{1}{\sqrt{R}}, \,R\geq 2.
		\end{equation}

		\item  If $\lambda>0$, then 
		\begin{equation}
			\mathbb{P}[|\mathfrak{T}_x|_{x,\lambda}\geq R]\asymp_{\lambda} R^{-\frac{1}{\lambda}}, \,R\geq 2.
		\end{equation}



	\end{itemize}

For all vertices $x_0,x_1,x_2$ we have 
 	\begin{equation}
 	\tau(x_0,x_1,x_2)\leq \sum_{u\in V} \tau(x_0,u)\tau(u,x_1)\tau(u,x_2)
 	\end{equation}

Suppose $x_0,x_1,\ldots,x_k$ are (possibly non-distinct) vertices of $G$. Then 
	\begin{equation}
	\tau(x_0,x_1,\ldots,x_k)\leq \sum_S\sum_{\varphi_{\mathbf{x}}}\prod_{(u,v)\in E(S)}\tau(\varphi_{\mathbf{x}}(u),\varphi_{\mathbf{x}}(v))
	\end{equation} 
	where the first sum is over all labelled skeleton with $k+1$ exterior vertices and the second sum is over all admissible maps $\varphi_{\mathbf{x}}$ from $V(S)$ to $V(G)$.

Let $X^x$ denote a simple random walk on the transitive graph $G$ started from $x$. Then  for $n\geq0$ one has that
 	\begin{equation}
 	\mathbb{P}[|\{X_m^x:m\geq0 \}\cap L_n(x)|\geq k]=e^{-\Theta(k)-t_0n}
 	\end{equation}
 	and 
 	\begin{equation}
 		\mathbb{P}[|\{X_m^x:m\geq0 \}\cap L_{-n}(x)|\geq k]=e^{-\Theta(k)}
 	\end{equation}
 	In particular, one has that
 	\begin{equation}
 	\mathbb{P}[\{X_m^x:m\geq0 \}\cap L_n(x)\neq\emptyset]\asymp \exp(-t_0n),n\geq0.
 	\end{equation}
 	Also a simple consequence is that there exists a constant $c>0$ such that
 	\begin{equation}
 	\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|^k]\leq
 	\left\{\begin{array}{cc}
 	c^kk!\exp(-t_0n)& \textnormal{ if }\,n\geq0\\
 	c^kk!& \textnormal{ if }\,n<0
 	\end{array}\right..
 	\end{equation}

 }
